import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`cold-email`,heroTitle:`Write your cold emails in minutes`,heroSubtitle:`Perplexity Computer researches prospects, personalizes every line, and builds complete email sequences - automatically.`,inputUrlCta:`Write my emails`,inputUrlPlaceholder:`Your prospect list`,inputUrlPrefill:`Go to {url} and treat it as my prospect list or target company. Research each company's recent news, funding rounds, leadership changes, and likely pain points. Then write 100 personalized cold email sequences - each with a unique subject line, personalized opening line referencing something specific about the prospect, a clear value proposition, and a call to action. Include A/B subject line variants for every email and send-time recommendations based on the prospect's industry and time zone. Deliver everything in a structured format I can import into my outreach tool.`,heroOverlaySteps:[`Researching each prospect's company news, funding, and pain points`,`Personalizing subject lines and opening lines for every recipient`,`Writing complete cold email sequences with A/B variants`,`100 ready-to-send emails with send-time recommendations - ready to launch`],generatingSteps:[`Visiting {url} to extract prospect details and target accounts`,`Designing an agent to research company news, pain points, and triggers for each prospect`,`Configuring personalized email sequences with A/B subject line variants per recipient`,`Setting up send-time optimization and export formatting for your outreach tool`],featureSectionTitle:`From prospect list to sent folder`,featureCardTitles:[`Connects to your sales stack`,`Outputs you can send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Pipedrive, Slack, Notion - Computer plugs into your tools so research, writing, and sending happen in one workflow.`,`Personalized email sequences. A/B subject line variants. Send-time recommendations. Prospect research briefs. Computer delivers outreach you can load into your tool and launch.`],capabilitySectionTitle:`Your sales rep, on autopilot`,capabilitySectionSubtitle:`Upload your list, step away, come back to 100 ready-to-send emails.`,capabilityCards:[{title:`Prospect Research`,description:`Computer can dig into each company's recent news, funding rounds, hiring signals, and pain points - and surface the hooks that get replies.`},{title:`Email Personalization`,description:`Computer can write unique subject lines and opening lines for every recipient - referencing specific triggers so nothing reads like a template.`},{title:`Sequence Building`,description:`Computer can draft multi-step email sequences with follow-ups, A/B variants, and escalation logic - structured for your outreach cadence.`},{title:`Connect Your Tools`,description:`Computer can read and write to Gmail, Google Sheets, Pipedrive, Slack, and more - build workflows across your entire sales stack.`},{title:`Remember & Learn`,description:`Computer can remember your value props, ICP, and tone across sessions - so every batch of emails builds on what's worked before.`},{title:`Monitor & Alert`,description:`Computer can track reply rates and bounce signals - set up a monitoring workflow that flags underperforming sequences so you can iterate fast.`}]});export{t as default};
